bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {videoOfferLink} from './src/telegram/videoInvoiceSales.mjs';
const e=process.env;
if(e.VIDEOBOT_DB_NAME!=='videobot'||e.VIDEO_SALE_MODE!=='invoice')throw Error('VIDEO_RUNTIME_OWNER_OR_MODE_UNVERIFIED');
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
try{
 const row=(await pool.query("SELECT l.listing_id,l.revision,l.price_stars,l.seller_user_id,l.sample_file_id,l.status listing_status,r.sale_mode,r.status receipt_status,r.free_message_ids,r.paid_message_id,r.topic_id FROM videobot_listings l JOIN videobot_post_receipts r ON l.listing_id=r.listing_id WHERE r.delivery_key='v26nov24invoice:1'")).rows[0];
 if(!row||row.listing_status!=='published'||row.sale_mode!=='invoice'||row.receipt_status!=='sent'||row.free_message_ids?.length!==2||!row.paid_message_id||Number(row.paid_message_id)===Number(row.free_message_ids[1]))throw Error('CURRENT_POST_RECEIPT_NOT_SEPARATE');
 const api=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000});
 const gate=await createGateOwner({pool,telegramApi:api});
 const topic=await gate.getVerifiedVideoTopic({purpose:'video_sale',sellerId:String(row.seller_user_id),listingId:row.listing_id});
 if(topic?.verified!==true||topic?.purpose!=='video_sale'||topic?.board!=='video_chat'||topic?.enabled!==true||topic?.threadId!==Number(row.topic_id)||!Number.isSafeInteger(topic.chatId)||topic.chatId>=0)throw Error('VIDEO_TOPIC_UNVERIFIED');
 const me=await api('getMe',{});
 const url=videoOfferLink(me.username,row.listing_id,Number(row.revision));
 const text='⭐ 本編を購入（'+row.price_stars+' Stars）';
 const sampleId=Number(row.free_message_ids[1]);
 const token=readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE);
 const resp=await net.fetch('https://api.telegram.org/bot'+token+'/editMessageMedia',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({chat_id:topic.chatId,message_id:sampleId,media:{type:'video',media:row.sample_file_id,has_spoiler:true,caption:'⭐ 本編の購入はこちら'},reply_markup:{inline_keyboard:[[{text,url}]]}}),signal:AbortSignal.timeout(25000),redirect:'error'});
 const data=await resp.json();
 const reply=data.result;
 let kind='OTHER';
 const raw=String(data?.description??'').toLowerCase();
 if(data.ok===true)kind='SUCCESS';
 else if(raw.includes('message is not modified'))kind='ALREADY_MODIFIED';
 else if(raw.includes('message to edit not found')||raw.includes('message to be edited not found'))kind='NOT_FOUND';
 else if(raw.includes("can't be edited")||raw.includes('cannot be edited'))kind='EDIT_NOT_SUPPORTED';
 else if(raw.includes('message_id_invalid'))kind='INVALID_MESSAGE_ID';
 else if(raw.includes('reply markup'))kind='REPLY_MARKUP_REJECTED';
 const found=reply?.reply_markup?.inline_keyboard?.[0]?.[0];
 const verified=kind==='SUCCESS'&&reply?.message_id===sampleId&&found?.text===text&&found?.url===url&&!!reply?.media_group_id;
 console.log('ALBUM_MEDIA_EDIT_AND_BUTTON='+JSON.stringify({responseOk:data.ok===true,http:resp.status,reason:kind,albumMember:!!reply?.media_group_id,markupMatches:found?.text===text&&found?.url===url,verified}));
 if(!verified){
   if(kind==='SUCCESS'){
     // Undo only the sample caption if the keyboard did not attach.
     const undo=await net.fetch('https://api.telegram.org/bot'+token+'/editMessageCaption',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({chat_id:topic.chatId,message_id:sampleId,caption:''}),signal:AbortSignal.timeout(25000),redirect:'error'});
     const restored=await undo.json();
     console.log('SAMPLE_CAPTION_RESTORED='+JSON.stringify({ok:restored.ok===true,http:undo.status}));
   }
   throw Error('ALBUM_MEDIA_EDIT_AND_BUTTON_NOT_VERIFIED');
 }
}finally{await net.close();await pool.end()}
NODE
